export function Product({ route, navigation }: ScreenProps<'Product'>) {
  const [item, setItem] = useState<P | null>(null);
  const add = useCart(s => s.add);
  const count = useCart(s => s.items.reduce((n, i) => n + i.qty, 0));
  useEffect(() => {
